import vectors from '../../docs/vectors.json';
import {
  CodecError,
  decodeCommand,
  decodeSession,
  decodeStatus,
  encodeCommand,
  encodeSession,
  encodeStatus,
  fromBase64,
  fromHex,
  toBase64,
  toHex,
} from '../protocol/codec';
import { FAULT_NAMES, RESULT_NAMES, STATE_NAMES, type Opcode } from '../protocol/constants';
import { guardBitsOf } from '../protocol/messages';

// Vectors generated by importing tools/ble_client.py (see docs/CONTRACT.md "Reference encodings").
describe('command frames match ble_client.pack_command byte-for-byte', () => {
  it.each(vectors.commands.map((c) => [c.opcode_name, c.counter, c.nonce, c.hex] as const))(
    '%s counter=%d nonce=%d -> %s',
    (_n, counter, nonce, hex) => {
      const c = vectors.commands.find((x) => x.hex === hex)!;
      const bytes = encodeCommand({ opcode: c.opcode as Opcode, counter, nonce });
      expect(bytes).toHaveLength(9);
      expect(toHex(bytes)).toBe(hex);
      expect(decodeCommand(fromHex(hex))).toEqual({ opcode: c.opcode, counter, nonce });
    },
  );
  it('covers every opcode', () => {
    expect(new Set(vectors.commands.map((c) => c.opcode))).toEqual(new Set([1, 2, 3]));
  });
  it('masks counter/nonce to uint32 like ble_client', () => {
    expect(toHex(encodeCommand({ opcode: 1, counter: 2 ** 32 + 5, nonce: -1 }))).toBe('0105000000ffffffff');
  });
});

describe('status payloads match ble_client.parse_status', () => {
  it.each(vectors.statuses.map((s) => [s.description, s.hex] as const))('%s', (_d, hex) => {
    const v = vectors.statuses.find((s) => s.hex === hex)!.decoded;
    const s = decodeStatus(fromHex(hex));
    expect(s).toEqual({
      state: v.state,
      lastResult: v.last_result,
      fault: v.fault,
      guardFailMask: v.guard_fail_mask,
      zoneClear: v.zone_clear,
      sensorsValid: v.sensors_valid,
      ownerConnected: v.owner_connected,
      batteryMv: v.battery_mv,
      lastCounter: v.last_counter,
    });
    expect(STATE_NAMES[s.state as keyof typeof STATE_NAMES]).toBe(v.state_name);
    expect(RESULT_NAMES[s.lastResult as keyof typeof RESULT_NAMES]).toBe(v.last_result_name);
    expect(FAULT_NAMES[s.fault as keyof typeof FAULT_NAMES]).toBe(v.fault_name);
    expect(guardBitsOf(s.guardFailMask)).toHaveLength(v.guard_fail_bits.length);
    // round trip (reserved byte is 0 in every vector)
    expect(toHex(encodeStatus(s))).toBe(hex);
  });
  it.each(vectors.invalid_status_lengths.map((x) => [x.len, x.hex] as const))(
    'rejects %d-byte payload like ble_client (ValueError)',
    (_len, hex) => {
      expect(() => decodeStatus(fromHex(hex))).toThrow(CodecError);
    },
  );
});

describe('session nonce', () => {
  it.each(vectors.session_nonces.map((n) => [n.hex, n.nonce] as const))('%s -> %d', (hex, nonce) => {
    expect(decodeSession(fromHex(hex))).toBe(nonce);
    expect(toHex(encodeSession(nonce))).toBe(hex);
  });
  it('rejects wrong length', () => {
    expect(() => decodeSession(new Uint8Array(3))).toThrow(CodecError);
  });
});

describe('base64 (ble-plx value encoding)', () => {
  it('round-trips all lengths', () => {
    for (let n = 0; n < 20; n++) {
      const b = Uint8Array.from({ length: n }, (_, i) => (i * 37 + n) & 0xff);
      expect(fromBase64(toBase64(b))).toEqual(b);
    }
  });
  it('matches known encodings', () => {
    expect(toBase64(fromHex('010100000000000000'))).toBe('AQEAAAAAAAAA');
    expect(toBase64(fromHex('efbeadde'))).toBe('776t3g==');
    expect(toHex(fromBase64('776t3g=='))).toBe('efbeadde');
  });
});
